import pickle

def sentiment(text: str) -> float:
    with open('models/sentiment_v3.pkl', 'rb') as f:
        model = pickle.load(f)
    return round(model.predict([text])[0], 3)

def second_largest(nums: list) -> int:
    unique_nums = list(set(nums))
    if len(unique_nums) < 2:
        raise ValueError("Not enough distinct elements")
    unique_nums.sort()
    return unique_nums[-2]

def shipping_cost(kg: float) -> float:
    if kg <= 1:
        return 5.0
    return 5.0 + 2.0 * int(kg)

def merge_intervals(iv: list) -> list:
    if not iv:
        return []

    # Sort intervals by start time
    iv.sort()

    merged = [iv[0]]

    for current in iv[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping or adjacent, merge them
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)

    return merged

def run_length_encode(s: str) -> str:
    if not s:
        return ''
    result = []
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f'{current_char}{count}')
            current_char = char
            count = 1
    result.append(f'{current_char}{count}')
    return ''.join(result)

